(() => {
  'use strict';

  const $ = (selector, root = document) => root.querySelector(selector);
  const $$ = (selector, root = document) => Array.from(root.querySelectorAll(selector));
  const root = document.documentElement;
  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Set the copyright year.
  $('#year').textContent = new Date().getFullYear();

  // All icons are generated by the local, dependency-free icons.js file.
  // Theme: stores only a non-sensitive visual preference in localStorage.
  const themeButton = $('.theme-toggle');
  let savedTheme = null;
  try { savedTheme = localStorage.getItem('techfix-theme'); } catch (_) { /* storage can be blocked */ }
  if (savedTheme === 'light' || savedTheme === 'dark') root.dataset.theme = savedTheme;
  const updateThemeLabel = () => {
    const light = root.dataset.theme === 'light';
    themeButton.setAttribute('aria-label', light ? 'تفعيل الوضع الداكن' : 'تفعيل الوضع الفاتح');
  };
  updateThemeLabel();
  themeButton.addEventListener('click', () => {
    root.dataset.theme = root.dataset.theme === 'light' ? 'dark' : 'light';
    try { localStorage.setItem('techfix-theme', root.dataset.theme); } catch (_) { /* no-op */ }
    updateThemeLabel();
  });

  // Mobile navigation.
  const menuToggle = $('.menu-toggle');
  const nav = $('#primary-nav');
  const closeMenu = () => {
    nav.classList.remove('open');
    menuToggle.setAttribute('aria-expanded', 'false');
    menuToggle.setAttribute('aria-label', 'فتح القائمة');
  };
  menuToggle.addEventListener('click', () => {
    const opening = !nav.classList.contains('open');
    nav.classList.toggle('open', opening);
    menuToggle.setAttribute('aria-expanded', String(opening));
    menuToggle.setAttribute('aria-label', opening ? 'إغلاق القائمة' : 'فتح القائمة');
  });
  $$('.nav-link', nav).forEach(link => link.addEventListener('click', closeMenu));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && nav.classList.contains('open')) {
      closeMenu();
      menuToggle.focus();
    }
  });
  document.addEventListener('click', event => {
    if (nav.classList.contains('open') && !nav.contains(event.target) && !menuToggle.contains(event.target)) closeMenu();
  });

  // Header state, back-to-top button, and active section tracking.
  const header = $('.site-header');
  const topButton = $('.back-to-top-fab');
  const onScroll = () => {
    const y = window.scrollY;
    header.classList.toggle('scrolled', y > 12);
    topButton.classList.toggle('visible', y > 550);
  };
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();
  topButton.addEventListener('click', () => window.scrollTo({ top: 0, behavior: reducedMotion ? 'auto' : 'smooth' }));

  const sections = $$('main section[id]');
  const navLinks = $$('.nav-link');
  if ('IntersectionObserver' in window) {
    const sectionObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        navLinks.forEach(link => {
          const active = link.getAttribute('href') === `#${entry.target.id}`;
          link.classList.toggle('active', active);
          if (active) link.setAttribute('aria-current', 'location');
          else link.removeAttribute('aria-current');
        });
      });
    }, { rootMargin: '-32% 0px -58% 0px', threshold: 0 });
    sections.forEach(section => sectionObserver.observe(section));
  }

  // Reveal sections only when motion is allowed; content stays visible without the API.
  const revealItems = $$('.reveal');
  if (!reducedMotion && 'IntersectionObserver' in window) root.classList.add('js-ready');
  // Keyboard users can reveal a section immediately when one of its descendants receives focus.
  document.addEventListener('focusin', event => {
    if (!(event.target instanceof Element)) return;
    const reveal = event.target.closest('.reveal:not(.is-visible)');
    if (reveal) reveal.classList.add('is-visible');
  });
  if (!reducedMotion && 'IntersectionObserver' in window) {
    const revealObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.08, rootMargin: '0px 0px -25px 0px' });
    revealItems.forEach((el, index) => {
      const delay = index % 5;
      if (delay > 0) el.classList.add(`reveal-delay-${delay}`);
      revealObserver.observe(el);
    });
  } else {
    revealItems.forEach(el => el.classList.add('is-visible'));
  }

  // Gentle terminal typing effect. These are display-only strings and never executed.
  const commands = $$('.terminal-command');
  if (!reducedMotion && commands.length) {
    commands.forEach((el, index) => {
      const fullText = el.dataset.command || el.textContent;
      el.textContent = '';
      el.classList.add('typing');
      let i = 0;
      const typeNext = () => {
        el.textContent = fullText.slice(0, i);
        i += 1;
        if (i <= fullText.length) window.setTimeout(typeNext, 52 + Math.random() * 35);
        else el.classList.remove('typing');
      };
      window.setTimeout(typeNext, 450 + index * 640);
    });
  }

  // Project category filter.
  const filterButtons = $$('.filter-button');
  const projectCards = $$('.project-card');
  filterButtons.forEach(button => {
    button.addEventListener('click', () => {
      const filter = button.dataset.filter;
      filterButtons.forEach(item => {
        const active = item === button;
        item.classList.toggle('active', active);
        item.setAttribute('aria-pressed', String(active));
      });
      projectCards.forEach(card => {
        card.hidden = !(filter === 'all' || card.dataset.category === filter);
      });
    });
  });

  // Accessible toast for service detail actions.
  const toast = $('#toast');
  const toastMessage = $('#toast-message');
  let toastTimer;
  const showToast = message => {
    toastMessage.textContent = message;
    toast.classList.add('show');
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => toast.classList.remove('show'), 4600);
  };
  $('.toast button').addEventListener('click', () => toast.classList.remove('show'));
  $$('.service-detail').forEach(button => {
    button.addEventListener('click', () => {
      const serviceName = button.dataset.service;
      const serviceField = $('#service');
      const matchingOption = Array.from(serviceField.options).find(option => option.textContent.trim().includes(serviceName));
      if (matchingOption) serviceField.value = matchingOption.value || matchingOption.textContent;
      $('#contact-form').scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'start' });
      window.setTimeout(() => $('#name').focus({ preventScroll: true }), reducedMotion ? 0 : 450);
      showToast(`تم اختيار خدمة «${serviceName}». أضف تفاصيل طلبك في نموذج التواصل.`);
    });
  });

  // Message length counter.
  const messageField = $('#message');
  const messageCount = $('#message-count');
  const updateMessageCount = () => { messageCount.textContent = `${messageField.value.length} / 2000`; };
  messageField.addEventListener('input', updateMessageCount);
  updateMessageCount();

  // Front-end validation; no visitor data is sent or saved. Submission opens the visitor's mail app.
  const form = $('#contact-form');
  const status = $('#form-status');
  const allowedServices = new Set(Array.from($('#service').options, option => option.value).filter(Boolean));
  const fields = {
    name: { input: $('#name'), error: $('#name-error'), label: 'الاسم', validate: value => value.trim().length >= 2 && value.trim().length <= 80 },
    email: { input: $('#email'), error: $('#email-error'), label: 'البريد الإلكتروني', validate: value => value.trim().length <= 120 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim()) },
    service: { input: $('#service'), error: $('#service-error'), label: 'نوع الخدمة', validate: value => allowedServices.has(value.trim()) },
    message: { input: $('#message'), error: $('#message-error'), label: 'تفاصيل الطلب', validate: value => value.trim().length >= 10 && value.trim().length <= 2000 }
  };
  const validationMessage = (key, value) => {
    const clean = value.trim();
    if (!clean) return 'هذا الحقل مطلوب.';
    if (key === 'name' && clean.length < 2) return 'اكتب اسماً من حرفين على الأقل.';
    if (key === 'name' && clean.length > 80) return 'الاسم أطول من الحد المسموح.';
    if (key === 'email' && !fields.email.validate(clean)) return 'أدخل بريداً إلكترونياً صحيحاً لا يتجاوز 120 حرفاً.';
    if (key === 'service' && !fields.service.validate(clean)) return 'اختر خدمة من القائمة المتاحة.';
    if (key === 'message' && clean.length < 10) return 'اكتب تفاصيل أكثر (10 أحرف على الأقل).';
    if (key === 'message' && clean.length > 2000) return 'الرسالة أطول من الحد المسموح.';
    return '';
  };
  const validateField = key => {
    const field = fields[key];
    const errorText = validationMessage(key, field.input.value);
    field.error.textContent = errorText;
    field.input.setAttribute('aria-invalid', String(Boolean(errorText)));
    return !errorText;
  };
  Object.keys(fields).forEach(key => {
    const field = fields[key];
    field.input.addEventListener('blur', () => validateField(key));
    field.input.addEventListener('input', () => {
      if (field.input.hasAttribute('aria-invalid')) validateField(key);
      status.textContent = '';
    });
    field.input.addEventListener('change', () => {
      if (field.input.hasAttribute('aria-invalid')) validateField(key);
    });
  });

  form.addEventListener('submit', event => {
    event.preventDefault();
    status.textContent = '';
    if ($('#website').value.trim()) {
      status.textContent = 'تعذّر تجهيز الطلب. حاول مرة أخرى.';
      return;
    }
    const keys = Object.keys(fields);
    const isValid = keys.map(validateField).every(Boolean);
    if (!isValid) {
      const firstInvalid = keys.map(key => fields[key]).find(field => field.input.getAttribute('aria-invalid') === 'true');
      if (firstInvalid) firstInvalid.input.focus();
      status.textContent = 'راجع الحقول المحددة ثم حاول مجدداً.';
      return;
    }
    const name = fields.name.input.value.trim();
    const email = fields.email.input.value.trim();
    const service = fields.service.input.value.trim();
    const message = fields.message.input.value.trim();
    const subject = `طلب خدمة: ${service} — ${name}`;
    const body = `الاسم: ${name}\nالبريد الإلكتروني: ${email}\nنوع الخدمة: ${service}\n\nتفاصيل الطلب:\n${message}\n\n---\nتم تجهيز هذه الرسالة من نموذج TECH FIX.`;
    const mailto = `mailto:mh312177@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    status.textContent = 'سيتم فتح تطبيق البريد لإكمال الإرسال. لن تُرسل الرسالة من الموقع مباشرة.';
    window.location.href = mailto;
  });

  // Keep phone/WhatsApp/profile details centralized here if you adapt the contact section.
  // The supplied phone number is shown as entered. WhatsApp assumes Sudan's +249 country code;
  // verify that number before publishing if the supplied number belongs to another country.
})();
